/* Generate react-spectrum-s2-font.css from react-spectrum-s2.css.
 *
 * S2 sets font-family through atomic classes inside `@layer _.*`
 * (`.uk17 { font-family: var(--s2-font-family-sans, adobe-clean-spectrum-vf), … }`,
 * plus one class per script, e.g. `.uic17:is(:lang(zh-Hans),:lang(zh-CN),…)` → SimSun).
 * The prototype's type stack is `--sans` (Source Sans 3 first, see app/tokens.css),
 * so this emits one UNLAYERED rule with every such selector → `var(--sans)`.
 * Unlayered beats layered, so it wins without !important.
 *
 * The class hashes change when the bundle is rebuilt, which is why this file is
 * generated (build.mjs calls it) and must never be hand-edited.
 *
 *   node font-override.mjs [dir]   # dir holds react-spectrum-s2.css; default ..
 */
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

export function fontOverride(css) {
  const sels = [];
  for (const m of css.matchAll(/([^{}]+)\{font-family:([^;}]+)[;}]/g)) {
    const sel = m[1].trim();
    if (m[2].trim() === 'inherit' || sel.startsWith('@')) continue;
    if (!sels.includes(sel)) sels.push(sel);
  }
  if (!sels.length) throw new Error('no S2 font-family rules found — did the bundle format change?');
  return '/* GENERATED by build/font-override.mjs from react-spectrum-s2.css — do not edit.\n' +
    '   Unlayered on purpose: S2 font classes live in @layer _.*; this points them at the\n' +
    '   prototype type stack (--sans, Source Sans 3 first). */\n' +
    sels.join(',\n') + ' {\n  font-family: var(--sans);\n}\n';
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const dir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), process.argv[2] || '..');
  const css = fs.readFileSync(path.join(dir, 'react-spectrum-s2.css'), 'utf8');
  const out = path.join(dir, 'react-spectrum-s2-font.css');
  fs.writeFileSync(out, fontOverride(css));
  console.log(out);
}
